import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3, x4 = x
    return (x1**4 + x2**4 + x3**4 + x4**4) + 0.5*(x1 + x2 - x3 - x4) + 0.1*np.cos(5*(x1**2 + x2**2 + x3**2 + x4**2))

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3, x4 = x
    return 0.1 * (x1**4 + x2**4 + x3**4 + x4**4) + 0.2 * (np.cos(x1 * x2) + np.cos(x3 * x4)) + 0.1 * (x1 + 2*x2 + 0.5*x3 + x4)
